async function database(suffix){const name=prefix+'_'+suffix;assert(/^storage_recovery_[a-f0-9]{32}_(source|intact|rollback)$/.test(name));await admin.query('CREATE DATABASE '+name);owned.push(name);const connection=new URL(url);connection.pathname='/'+name;connection.search='';const pool=new Pool({connectionString:connection.toString()});pools.push(pool);const app=buildApp(pool);apps.push(app);return{name,pool,app};}
async function authorize(pool,a,create=false){
 if(create){await pool.query("INSERT INTO users(id,organization_id,login,password_hash,role) VALUES($1::uuid,$2,$1::uuid::text,'test-only','chief')",[a.actor,org]);await pool.query('INSERT INTO devices(id,organization_id,user_id) VALUES($1,$2,$3)',[a.device,org,a.actor]);}
 await pool.query("INSERT INTO sessions(id,organization_id,user_id,token_hash,expires_at) VALUES($1,$2,$3,$4,now()+interval '1 hour')",[randomUUID(),org,a.actor,tokenHash(a.token)]);
 await pool.query("INSERT INTO device_proof_grants(token_hash,organization_id,user_id,device_id,session_token_hash,expires_at) VALUES($1,$2,$3,$4,$5,now()+interval '1 hour')",[tokenHash(a.proof),org,a.actor,a.device,tokenHash(a.token)]);
}
function headers(a=identity,epoch){return{authorization:'Bearer '+a.token,'x-device-proof':a.proof,...(epoch?{'x-inventory-epoch':epoch}:{})};}
async function post(db,path,payload,epoch,status=201,a=identity){if(!epoch&&['/inventory/materials','/inventory/locations'].includes(path))epoch=(await state(db,a)).epoch;const r=await db.app.inject({method:'POST',url:path,headers:headers(a,epoch),payload});assert.equal(r.statusCode,status,r.body);return r.json();}
async function state(db,a=identity){const r=await db.app.inject({method:'GET',url:'/inventory/stream?deviceId='+a.device,headers:headers(a)});assert.equal(r.statusCode,200,r.body);return r.json();}
async function snapshot(pool){const names=(await pool.query("SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename")).rows.map(r=>r.tablename);const result={};for(const name of names){assert(/^[a-z_0-9]+$/.test(name));result[name]=(await pool.query('SELECT row_to_json(t) AS row FROM "'+name+'" t')).rows.map(r=>JSON.stringify(r.row)).sort();}return result;}
async function restore(name,archive){await new Promise((resolve,reject)=>{const child=spawn('docker',[...docker,'exec','-i',container,'pg_restore','--exit-on-error','--no-owner','--no-privileges','-U','production_mf_ci','-d',name],{env:environment,stdio:['pipe','ignore','pipe']});let error='';child.stderr.on('data',data=>{error+=data.toString();});child.on('error',reject);child.stdin.on('error',reject);child.on('close',code=>code===0?resolve():reject(Error('pg_restore failed: '+error)));child.stdin.end(archive);});}
